#!/usr/bin/env python3
"""Build the deterministic, dependency-free README SVG system."""
from pathlib import Path
import json, html
ROOT=Path(__file__).resolve().parents[2]; OUT=ROOT/'assets/readme'; OUT.mkdir(parents=True,exist_ok=True)
reg=json.loads((ROOT/'gateway/data/policies.registry.json').read_text()); providers=list(reg['providers']); models=reg['models']
BG='#0A0908'; PANEL='#141210'; RED='#D60019'; CYAN='#22D3EE'; GREEN='#34D399'; INK='#F4F1EB'; MUTED='#928C82'; LINE='#332D28'

def esc(x): return html.escape(str(x))
def svg(title, subtitle, body, width=1200, height=560, animate=False):
    motion='''<style>@keyframes rail{to{transform:translateX(760px)}} .pulse{animation:rail 4s linear infinite} @media (prefers-reduced-motion:reduce){.pulse{animation:none}}</style>''' if animate else '<style>@media (prefers-reduced-motion:reduce){*{animation:none!important}}</style>'
    return f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {width} {height}" role="img" aria-labelledby="t d"><title id="t">{esc(title)}</title><desc id="d">{esc(subtitle)}</desc>{motion}<rect width="100%" height="100%" fill="{BG}"/><path d="M0 72H{width} M0 530H{width}" stroke="{LINE}"/><text x="42" y="48" fill="{INK}" font-family="monospace" font-size="24" font-weight="700" letter-spacing="3">{esc(title).upper()}</text><text x="42" y="98" fill="{MUTED}" font-family="monospace" font-size="15">{esc(subtitle)}</text>{body}</svg>'''

def node(x,y,w,h,label,accent=LINE,small=''):
 extra = f'<text x="{x+18}" y="{y+60}" fill="{MUTED}" font-family="monospace" font-size="12">{esc(small)}</text>' if small else ''
 return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="8" fill="{PANEL}" stroke="{accent}" stroke-width="2"/><text x="{x+18}" y="{y+35}" fill="{INK}" font-family="monospace" font-size="16" font-weight="700">{esc(label)}</text>{extra}'

def write(name,title,subtitle,body,animate=False): (OUT/name).write_text(svg(title,subtitle,body,animate=animate))
write('hero.svg','KONKRED / CONTROL RAIL','multi-provider AI gateway + Telegram runtime',node(70,190,210,100,'TELEGRAM',' #2d2723','message intake')+node(350,190,210,100,'BOT / FSM',CYAN,'memory + chunking')+node(630,190,210,100,'GATEWAY',RED,'policy + quota + fallback')+node(910,150,210,180,'PROVIDER POOL',GREEN,f'{len(providers)} registry providers / {len(models)} models')+'<path d="M280 240H350M560 240H630M840 240H910" stroke="'+CYAN+'" stroke-width="4"/><circle class="pulse" cx="90" cy="240" r="7" fill="'+RED+'"/>',True)
write('provider-rack.svg','PROVIDER RACK','registry-backed adapters; mock is the offline simulator', ''.join(node(70+(i%4)*275,150+(i//4)*150,230,92,p.upper(), GREEN if p!='mock' else MUTED, f'{sum(m["providerId"]==p for m in models)} models') for i,p in enumerate(providers)))
write('gateway-core.svg','GATEWAY CORE','one controlled API rail',node(90,180,240,120,'HTTP CONTRACT',RED,'/api/ai + envelopes')+node(480,180,240,120,'POLICY STORE',CYAN,'registry + privacy')+node(870,180,240,120,'KEY POOL',GREEN,'quota windows')+'<path d="M330 240H480M720 240H870" stroke="#D60019" stroke-width="4"/>')
write('routing-engine.svg','ROUTING ENGINE','rank candidates by task, privacy, quota, health',node(80,170,220,150,'TASK',' #735','general / code / translate')+node(350,170,220,150,'PRIVACY',CYAN,'private excludes training')+node(620,170,220,150,'QUOTA',GREEN,'RPM / TPM / day')+node(890,170,220,150,'HEALTH',RED,'cooldown-aware')+'<path d="M300 245H350M570 245H620M840 245H890" stroke="'+CYAN+'" stroke-width="3"/>')
write('quota-ledger.svg','QUOTA LEDGER','sliding windows reserve before dispatch',node(90,170,300,150,'RESERVE',' #735','estimate tokens')+node(450,170,300,150,'COMMIT',GREEN,'actual usage')+node(810,170,300,150,'RESET',CYAN,'provider policy')+'<path d="M390 245H450M750 245H810" stroke="'+GREEN+'" stroke-width="3"/><path d="M110 390h980" stroke="'+LINE+'" stroke-width="14"/><path d="M110 390h690" stroke="'+GREEN+'" stroke-width="14"/>')
write('fallback-sequence.svg','FALLBACK SEQUENCE','classified failure → next viable candidate → cooldown',node(70,170,200,120,'429',' #735','rate limit')+node(310,170,200,120,'401 / 403',RED,'disable key')+node(550,170,200,120,'5xx',CYAN,'provider fault')+node(790,170,200,120,'CONTEXT',GREEN,'trim once')+node(1020,170,120,120,'NEXT',' #735','model/key')+'<path d="M270 230H310M510 230H550M750 230H790M990 230H1020" stroke="'+RED+'" stroke-width="3"/>')
write('cache-dedup.svg','CACHE / DEDUP','cached response is not shared in-flight work',node(100,170,360,140,'CACHE HIT',GREEN,'bounded LRU / TTL')+node(740,170,360,140,'IN-FLIGHT',CYAN,'same key shares promise')+'<path d="M460 240H740" stroke="'+LINE+'" stroke-width="8"/><circle cx="590" cy="240" r="10" fill="'+GREEN+'"/><circle cx="650" cy="240" r="10" fill="'+CYAN+'"/>')
write('request-lifecycle.svg','REQUEST LIFECYCLE','Telegram → Redis → gateway → provider → reply',node(50,180,170,100,'TG',RED,'update')+node(270,180,170,100,'BOT',CYAN,'FSM')+node(490,180,170,100,'REDIS',GREEN,'history')+node(710,180,170,100,'GW',RED,'route')+node(930,180,210,100,'POOL',GREEN,'inference')+'<path d="M220 230H270M440 230H490M660 230H710M880 230H930" stroke="'+CYAN+'" stroke-width="4"/><circle class="pulse" cx="60" cy="230" r="7" fill="'+RED+'"/>',True)
write('telegram-runtime.svg','TELEGRAM RUNTIME','multi-turn memory, FSM, retries, Telegram-safe delivery',node(90,170,240,140,'HANDLER',CYAN,'task selection')+node(480,170,240,140,'HISTORY',GREEN,'Redis / 24h TTL')+node(870,170,240,140,'CHUNKS',RED,'≤ 4096 UTF-16')+'<path d="M330 240H480M720 240H870" stroke="'+CYAN+'" stroke-width="3"/>')
write('redis-memory.svg','REDIS MEMORY','AOF state store; history and FSM are separate concerns',node(130,180,360,130,'CONVERSATION','GREEN','konkred:history:*')+node(710,180,360,130,'FSM STORAGE',CYAN,'Aiogram state')+'<path d="M490 245H710" stroke="'+RED+'" stroke-width="3"/>')
write('api-console.svg','API CONSOLE','real endpoint groups exposed by the server',node(80,150,320,220,'READ',' #735','GET /api/health\nGET /api/ready\nGET /api/models')+node(440,150,320,220,'INFER',RED,'POST /api/ai')+node(800,150,320,220,'ADMIN',CYAN,'GET /api/status\nPOST /api/admin/cache/flush') )
write('health-console.svg','HEALTH CONSOLE','liveness is not readiness',node(100,180,300,120,'/api/health',GREEN,'200: process + pool')+node(500,180,300,120,'/api/ready',CYAN,'503: all keys cooling')+node(900,180,220,120,'STATUS',RED,'admin deep view'))
write('verification-console.svg','VERIFICATION CONSOLE','offline mock smoke + unit suites are executable',node(90,160,300,160,'GATEWAY',GREEN,'check · test · smoke')+node(450,160,300,160,'BOT',CYAN,'compile · imports · tests')+node(810,160,300,160,'TOPOLOGY',RED,'compose · YAML · shell')+'<text x="90" y="400" fill="'+GREEN+'" font-family="monospace" font-size="18">● PASS WHEN EXECUTED · SKIP WHEN TOOLING IS ABSENT</text>')
write('docker-topology.svg','DOCKER TOPOLOGY','compose services and internal DNS',node(100,180,250,130,'bot',CYAN,'GATEWAY_URL=gateway:3000')+node(475,180,250,130,'gateway',RED,'port 3000')+node(850,180,250,130,'redis',GREEN,'6379 / AOF')+'<path d="M350 245H475M725 245H850" stroke="'+CYAN+'" stroke-width="4"/>')
write('deployment-map.svg','DEPLOYMENT MAP','local compose or Render blueprint',node(80,180,260,130,'LOCAL',GREEN,'docker compose')+node(470,180,260,130,'RENDER',CYAN,'web + worker')+node(860,180,260,130,'UPSTASH',RED,'external Redis option')+'<path d="M340 245H470M730 245H860" stroke="'+LINE+'" stroke-width="4"/>')
write('footer.svg','KONKRED / READY','controlled routes, observable failure, bounded state','<text x="80" y="250" fill="'+RED+'" font-family="monospace" font-size="52" font-weight="700">ROUTE / RESERVE / RECOVER</text><text x="82" y="300" fill="'+MUTED+'" font-family="monospace" font-size="18">A rail is only resilient when its limits are visible.</text>')
print(f'generated {len(list(OUT.glob("*.svg")))} SVG assets')
